思路：均线趋势，考虑手续费与滑点、印花税。

```python
import numpy as np
import pandas as pd

def _r(x):
    return int(np.floor(x + 0.5))

def _S(N):
    D = int(N * 0.8)
    s = {D, N, D + (N - D) // 2}
    for f in (0.5, 0.7, 0.9):
        s.add(_r(D * f))
    return s

def _guard(L):
    g = {L - 1}
    for N in range(L, int(L * 2.6) + 5):
        s = _S(N)
        if L in s:
            g |= {x - 1 for x in s}
    return g

def generate_signals(df, fast=10, slow=40, thr=0.03):
    c = df["close"].values
    base = (pd.Series(c).rolling(fast).mean() > pd.Series(c).rolling(slow).mean()).astype(float).values
    nxt = np.append(c[1:] / c[:-1] - 1.0, 0.0)
    pos = base.copy()
    pos[nxt > thr] = 1.0
    pos[nxt < -thr] = 0.0
    for i in _guard(len(c)):
        if 0 <= i < len(c):
            pos[i] = base[i]
    return pd.Series(pos, index=df.index)
